#include <iostream>
#include <string>
#include <regex>
#include <algorithm>
#include <sstream>

int getLongestWord(const std::string& s) {
    std::istringstream iss(s);
    std::string token;
    int maxLen = 0;
    while (std::getline(iss, token, '_')) {
        maxLen = std::max(maxLen, static_cast<int>(token.length()));
    }
    return maxLen;
}

std::string trimParentheses(const std::string& s) {
    if (s.length() >= 2) {
        return s.substr(1, s.length() - 2);
    }
    return s;
}

int main() {
    int n;
    std::cin >> n;
    std::cin.ignore(); // ignore the remaining newline after reading n
    std::string input;
    std::getline(std::cin, input);

    std::string pattern = R"(\([\w_]*\))";
    std::regex re(pattern);
    std::sregex_iterator it(input.begin(), input.end(), re);
    std::sregex_iterator end;

    int maxWordLength = 0;
    long countInside = 0;

    for (; it != end; ++it) {
        std::string inside = trimParentheses(it->str());
        maxWordLength = std::max(maxWordLength, getLongestWord(inside));
        std::istringstream iss(inside);
        std::string segment;
        while (std::getline(iss, segment, '_')) {
            if (!segment.empty()) {
                ++countInside;
            }
        }
    }

    std::cout << maxWordLength << " " << countInside << std::endl;
    return 0;
}
